{"content":"import numpy as np
warnings_on = False

def branin(X):
    x1, x2 = X[:, 0], X[:, 1]
    return ((x2 - 5.1 / (4 * np.pi**2) * x1**2 + 5 / np.pi * x1 - 6)**2
            + 10 * (1 - 1 / (8 * np.pi)) * np.cos(x1) + 10)

rng1 = np.random.default_rng(1)
X = np.column_stack([rng1.uniform(-5, 10, 30), rng1.uniform(0, 15, 30)])
y = branin(X)
yn = (y - y.mean()) / y.std()
n = len(y)

def lml(l1, l2, v, nz):
    r2 = ((X[:, 0:1] - X[:, 0:1].T) / l1) ** 2 + ((X[:, 1:2] - X[:, 1:2].T) / l2) ** 2
    K = v * np.exp(-0.5 * r2) + nz * np.eye(n)
    try:
        L = np.linalg.cholesky(K)
        a = np.linalg.solve(L.T, np.linalg.solve(L, yn))
        return -0.5 * yn @ a - np.sum(np.log(np.diag(L))) - 0.5 * n * np.log(2 * np.pi)
    except Exception:
        return float('nan')

# our best ls/v
for (l1, l2, v) in [(4.5118, 24.52, 64.53), (4.5873, 31.246, 128.49)]:
    print('ls/v =', (l1, l2, v))
    for lnz in [-12, -10, -8, -6, -5, -4, -2, 0, 2]:
        print('  lnz=%3d  LML=%.3f' % (lnz, lml(l1, l2, v, np.exp(lnz))))
