import numpy as np
from gp_lite import GPRegressor, SquaredExponentialARD

def _branin(x):
    a, b = x[:,0], x[:,1]
    return (b - 5.12/(4.0*np.pi**2)*a**2 + 5.0/np.pi*a - 6.0)**2 + 10.0*np.sin(2.0*np.pi*a) + 10.0

def _lhs(n, d, seed=11):
    rng = np.random.default_rng(seed)
    pts = np.empty((n,d))
    for j in range(d):
        pts[:, j] = (rng.permutation(n) + rng.random(n))/n
    return pts

X = _lhs(30,2)*np.array([9.0,8.0]); y = _branin(X)
Xt = np.random.default_rng(8).random((200,2))*np.array([9.0,8.0]); yt = _branin(Xt)
s = np.std(yt)
best = (1e9,None)
for l1 in [0.5,0.8,1.0,1.5,2.0,3.0]:
  for l2 in [0.5,0.8,1.0,1.5,2.0,3.0]:
    for nz in [1e-6,1e-5,1e-4]:
        gp = GPRegressor(SquaredExponentialARD([l1,l2],1.0), noise=nz)
        gp.fit(X,y,optimize=False)
        r = np.sqrt(np.mean((gp.predict(Xt)-yt)**2))/s
        if r<best[0]: best=(r,(l1,l2,nz))
print('best', best)
# also with variance >1
for v in [2.0,5.0]:
  gp = GPRegressor(SquaredExponentialARD([best[1][0],best[1][1]],v), noise=best[1][2])
  gp.fit(X,y,optimize=False)
  print(v, np.sqrt(np.mean((gp.predict(Xt)-yt)**2))/s)
